import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = fileURLToPath(new URL('..', import.meta.url))
const source = JSON.parse(await readFile(join(root, 'design-system/tokens.json'), 'utf8'))

const kebab = (value) => value.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`)
const pascal = (value) => value[0].toUpperCase() + value.slice(1)

const cssLines = [
  '/* Generated by scripts/generate-design-tokens.mjs. Do not edit. */',
  ':root {'
]
for (const [name, value] of Object.entries(source.color.light)) cssLines.push(`  --br-color-${kebab(name)}: ${value};`)
for (const [name, value] of Object.entries(source.space)) cssLines.push(`  --br-space-${name}: ${value}px;`)
for (const [name, value] of Object.entries(source.radius)) cssLines.push(`  --br-radius-${name}: ${value}px;`)
for (const [name, value] of Object.entries(source.size)) cssLines.push(`  --br-size-${kebab(name)}: ${value}px;`)
for (const [name, value] of Object.entries(source.motion)) cssLines.push(`  --br-motion-${name}: ${value}ms;`)
cssLines.push('}', '', '@media (prefers-color-scheme: dark) {', '  :root {')
for (const [name, value] of Object.entries(source.color.dark)) cssLines.push(`    --br-color-${kebab(name)}: ${value};`)
cssLines.push('  }', '}', '')

const kotlinLines = [
  '// Generated by scripts/generate-design-tokens.mjs. Do not edit.',
  'package com.bookrealm.design.tokens',
  '',
  'import androidx.compose.ui.graphics.Color',
  'import androidx.compose.ui.unit.dp',
  'import androidx.compose.ui.unit.sp',
  '',
  'object BrLightColors {'
]
for (const [name, value] of Object.entries(source.color.light)) kotlinLines.push(`    val ${pascal(name)} = Color(0xFF${value.slice(1)})`)
kotlinLines.push('}', '', 'object BrDarkColors {')
for (const [name, value] of Object.entries(source.color.dark)) kotlinLines.push(`    val ${pascal(name)} = Color(0xFF${value.slice(1)})`)
kotlinLines.push('}', '', 'object BrSpacing {')
for (const [name, value] of Object.entries(source.space)) kotlinLines.push(`    val ${pascal(name)} = ${value}.dp`)
kotlinLines.push('}', '', 'object BrRadius {')
for (const [name, value] of Object.entries(source.radius)) kotlinLines.push(`    val ${pascal(name)} = ${value}.dp`)
kotlinLines.push('}', '', 'object BrSizes {')
for (const [name, value] of Object.entries(source.size)) kotlinLines.push(`    val ${pascal(name)} = ${value}.dp`)
kotlinLines.push('}', '', 'object BrTypeScale {')
for (const [name, value] of Object.entries(source.type)) {
  kotlinLines.push(`    val ${pascal(name)}FontSize = ${value.fontSize}.sp`)
  kotlinLines.push(`    val ${pascal(name)}LineHeight = ${value.lineHeight}.sp`)
}
kotlinLines.push('}', '')

const outputs = [
  ['docs/.vitepress/theme/br-tokens.css', `${cssLines.join('\n')}\n`],
  ['design-system/generated/BrTokens.kt', `${kotlinLines.join('\n')}\n`]
]
for (const [relativePath, content] of outputs) {
  const output = join(root, relativePath)
  await mkdir(dirname(output), { recursive: true })
  await writeFile(output, content)
}

console.log('Generated Web and Compose design tokens.')
